(62, 'evaluation_service.element', '{\"has_image\":[\"1\"],\"title\":\"Evaluation\",\"title_ar\":\"\\u062a\\u0642\\u064a\\u064a\\u0645\",\"description\":\"<span style=\\\"color:rgb(66,66,66);font-family:Inter, sans-serif;letter-spacing:normal;\\\">We have experts and offices specialized in evaluation to accurately determine the price of property in all its forms, whether it is land, residences, shops, farms, or factories.<\\/span><br \\/>\",\"description_ar\":\"\\u0644\\u062f\\u064a\\u0646\\u0627 \\u062e\\u0628\\u0631\\u0627\\u0621 \\u0648\\u0645\\u0643\\u0627\\u062a\\u0628 \\u0645\\u062a\\u062e\\u0635\\u0635\\u0629 \\u0641\\u064a \\u0627\\u0644\\u062a\\u0642\\u064a\\u064a\\u0645 \\u0644\\u062a\\u062d\\u062f\\u064a\\u062f \\u0633\\u0639\\u0631 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u0627\\u062a \\u0628\\u0643\\u0644 \\u0623\\u0634\\u0643\\u0627\\u0644\\u0647\\u0627 \\u0628\\u062f\\u0642\\u0629\\u060c \\u0633\\u0648\\u0627\\u0621 \\u0643\\u0627\\u0646\\u062a \\u0623\\u0631\\u0627\\u0636\\u064a \\u0623\\u0648 \\u0645\\u0633\\u0627\\u0643\\u0646 \\u0623\\u0648 \\u0645\\u062d\\u0644\\u0627\\u062a \\u062a\\u062c\\u0627\\u0631\\u064a\\u0629 \\u0623\\u0648 \\u0645\\u0632\\u0627\\u0631\\u0639 \\u0623\\u0648 \\u0645\\u0635\\u0627\\u0646\\u0639.<br \\/>\",\"service_request_url\":\"service-request\",\"image\":\"65bf4852167291707034706.png\"}', 'basic', '2024-02-04 02:18:26', '2024-02-05 20:57:44'),
(63, 'evaluation_service.element', '{\"has_image\":[\"1\"],\"title\":\"Studies\",\"title_ar\":\"\\u062f\\u0631\\u0627\\u0633\\u0627\\u062a\",\"description\":\"<span style=\\\"color:rgb(66,66,66);font-family:Inter, sans-serif;letter-spacing:normal;\\\">Property market is huge and has many needs, so an extensive market study is required before launching any project to know the needs and priorities of the segment that your company is addressing with this product.<\\/span><br \\/>\",\"description_ar\":\"\\u0633\\u0648\\u0642 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u0627\\u062a \\u0636\\u062e\\u0645 \\u0648\\u0644\\u0647 \\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a \\u0643\\u062b\\u064a\\u0631\\u0629\\u060c \\u0644\\u0630\\u0644\\u0643 \\u0644\\u0627 \\u0628\\u062f \\u0645\\u0646 \\u062f\\u0631\\u0627\\u0633\\u0629 \\u0633\\u0648\\u0642\\u064a\\u0629 \\u0645\\u0648\\u0633\\u0639\\u0629 \\u0642\\u0628\\u0644 \\u0625\\u0637\\u0644\\u0627\\u0642 \\u0623\\u064a \\u0645\\u0634\\u0631\\u0648\\u0639 \\u0644\\u0645\\u0639\\u0631\\u0641\\u0629 \\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a \\u0648\\u0623\\u0648\\u0644\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0634\\u0631\\u064a\\u062d\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u0633\\u062a\\u0647\\u062f\\u0641\\u0647\\u0627 \\u0634\\u0631\\u0643\\u062a\\u0643 \\u0628\\u0647\\u0630\\u0627 \\u0627\\u0644\\u0645\\u0646\\u062a\\u062c.<br \\/>\",\"service_request_url\":\"service-request\",\"image\":\"65bf486cbf1d51707034732.png\"}', 'basic', '2024-02-04 02:18:52', '2024-02-05 20:57:53'),
(64, 'social_investment_banner.content', '{\"has_image\":\"1\",\"title\":\"Social investment\",\"title_ar\":\"\\u0627\\u0644\\u0627\\u0633\\u062a\\u062b\\u0645\\u0627\\u0631 \\u0627\\u0644\\u0627\\u062c\\u062a\\u0645\\u0627\\u0639\\u064a\",\"description\":\"Lorem Ipsum is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry\'s standard dummy text ever since the 1500s\",\"description_ar\":\"\\u0644\\u0648\\u0631\\u064a\\u0645 \\u0625\\u064a\\u0628\\u0633\\u0648\\u0645 \\u0647\\u0648 \\u0628\\u0628\\u0633\\u0627\\u0637\\u0629 \\u0646\\u0635 \\u0648\\u0647\\u0645\\u064a \\u0645\\u0646 \\u0635\\u0646\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0637\\u0628\\u0627\\u0639\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0646\\u0636\\u064a\\u062f. \\u0644\\u0642\\u062f \\u0643\\u0627\\u0646 \\u0644\\u0648\\u0631\\u064a\\u0645 \\u0625\\u064a\\u0628\\u0633\\u0648\\u0645 \\u0647\\u0648 \\u0627\\u0644\\u0646\\u0635 \\u0627\\u0644\\u0648\\u0647\\u0645\\u064a \\u0627\\u0644\\u0642\\u064a\\u0627\\u0633\\u064a \\u0641\\u064a \\u0647\\u0630\\u0647 \\u0627\\u0644\\u0635\\u0646\\u0627\\u0639\\u0629 \\u0645\\u0646\\u0630 \\u0627\\u0644\\u0642\\u0631\\u0646 \\u0627\\u0644\\u0633\\u0627\\u062f\\u0633 \\u0639\\u0634\\u0631\",\"image\":\"65bf5571bacd51707038065.png\"}', 'basic', '2024-02-04 03:14:25', '2024-02-04 11:55:38'),
(65, 'social_investment_service.content', '{\"short_description\":\"We are unique in pioneering social investment by creating many qualitative projects for the sustainability of the non-profit third sector in partnership with our strategic partners with the aim of finding development solutions, models and local successful experiences through\",\"short_description_ar\":\"\\u0646\\u0646\\u0641\\u0631\\u062f \\u0628\\u0631\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062b\\u0645\\u0627\\u0631 \\u0627\\u0644\\u0627\\u062c\\u062a\\u0645\\u0627\\u0639\\u064a \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0627\\u0644\\u0639\\u062f\\u064a\\u062f \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0634\\u0627\\u0631\\u064a\\u0639 \\u0627\\u0644\\u0646\\u0648\\u0639\\u064a\\u0629 \\u0644\\u0627\\u0633\\u062a\\u062f\\u0627\\u0645\\u0629 \\u0627\\u0644\\u0642\\u0637\\u0627\\u0639 \\u0627\\u0644\\u062b\\u0627\\u0644\\u062b \\u063a\\u064a\\u0631 \\u0627\\u0644\\u0631\\u0628\\u062d\\u064a \\u0628\\u0627\\u0644\\u0634\\u0631\\u0627\\u0643\\u0629 \\u0645\\u0639 \\u0634\\u0631\\u0643\\u0627\\u0626\\u0646\\u0627 \\u0627\\u0644\\u0627\\u0633\\u062a\\u0631\\u0627\\u062a\\u064a\\u062c\\u064a\\u064a\\u0646 \\u0628\\u0647\\u062f\\u0641 \\u0625\\u064a\\u062c\\u0627\\u062f \\u0627\\u0644\\u062d\\u0644\\u0648\\u0644 \\u0648\\u0627\\u0644\\u0646\\u0645\\u0627\\u0630\\u062c \\u0627\\u0644\\u062a\\u0646\\u0645\\u0648\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062a\\u062c\\u0627\\u0631\\u0628 \\u0627\\u0644\\u0645\\u062d\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0646\\u0627\\u062c\\u062d\\u0629 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644\"}', 'basic', '2024-02-04 03:34:04', '2024-02-04 11:57:56'),
(66, 'social_investment_service.element', '{\"title\":\"A link between the third non-profit sector, the government and the private sector\",\"title_ar\":\"\\u062d\\u0644\\u0642\\u0629 \\u0648\\u0635\\u0644 \\u0628\\u064a\\u0646 \\u0627\\u0644\\u0642\\u0637\\u0627\\u0639 \\u0627\\u0644\\u062b\\u0627\\u0644\\u062b \\u063a\\u064a\\u0631 \\u0627\\u0644\\u0631\\u0628\\u062d\\u064a \\u0648\\u0627\\u0644\\u062d\\u0643\\u0648\\u0645\\u0629 \\u0648\\u0627\\u0644\\u0642\\u0637\\u0627\\u0639 \\u0627\\u0644\\u062e\\u0627\\u0635\"}', 'basic', '2024-02-04 03:34:12', '2024-02-04 11:58:07'),
