(184, 'target_sector.element', '{\"has_image\":\"1\",\"title\":\"Marketing path of vegetable markets\",\"title_ar\":\"\\u0627\\u0644\\u0645\\u0633\\u0627\\u0631 \\u0627\\u0644\\u062a\\u0633\\u0648\\u064a\\u0642\\u064a \\u0644\\u0623\\u0633\\u0648\\u0627\\u0642 \\u0627\\u0644\\u062e\\u0636\\u0627\\u0631\",\"image\":\"65f7414ead8c81710702926.png\"}', NULL, '2024-03-17 13:15:26', '2024-03-17 13:15:26'),
(185, 'target_sector.element', '{\"has_image\":\"1\",\"title\":\"The field of customs clearance Tourist track\",\"title_ar\":\"\\u0645\\u062c\\u0627\\u0644 \\u0627\\u0644\\u062a\\u062e\\u0644\\u064a\\u0635 \\u0627\\u0644\\u062c\\u0645\\u0631\\u0643\\u064a \\u0627\\u0644\\u0645\\u0633\\u0627\\u0631 \\u0627\\u0644\\u0633\\u064a\\u0627\\u062d\\u064a\",\"image\":\"65f74167d1a691710702951.png\"}', NULL, '2024-03-17 13:15:51', '2024-03-17 13:15:51'),
(186, 'program_duration.content', '{\"has_image\":\"1\",\"header\":\"Program Duration\",\"header_ar\":\"\\u0645\\u062f\\u0629 \\u0627\\u0644\\u0628\\u0631\\u0646\\u0627\\u0645\\u062c\",\"icon\":\"65f74293c2aff1710703251.png\"}', NULL, '2024-03-17 13:20:51', '2024-03-17 13:20:51'),
(187, 'program_duration.element', '{\"title\":\"From three months to six months\",\"title_ar\":\"\\u0645\\u0646 \\u062b\\u0644\\u0627\\u062b\\u0629 \\u0623\\u0634\\u0647\\u0631 \\u0625\\u0644\\u0649 \\u0633\\u062a\\u0629 \\u0623\\u0634\\u0647\\u0631\"}', NULL, '2024-03-17 13:21:11', '2024-03-17 13:21:11'),
(188, 'program_duration.element', '{\"title\":\"The program is held remotely and in person once a month\",\"title_ar\":\"\\u064a\\u064f\\u0639\\u0642\\u062f \\u0627\\u0644\\u0628\\u0631\\u0646\\u0627\\u0645\\u062c \\u0639\\u0646 \\u0628\\u064f\\u0639\\u062f \\u0648\\u0634\\u062e\\u0635\\u064a\\u064b\\u0627 \\u0645\\u0631\\u0629 \\u0648\\u0627\\u062d\\u062f\\u0629 \\u0634\\u0647\\u0631\\u064a\\u064b\\u0627\"}', NULL, '2024-03-17 13:21:22', '2024-03-17 13:21:22'),
(189, 'program_duration.element', '{\"title\":\"Training for three hours a day remotely\",\"title_ar\":\"\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0644\\u0645\\u062f\\u0629 \\u062b\\u0644\\u0627\\u062b \\u0633\\u0627\\u0639\\u0627\\u062a \\u0641\\u064a \\u0627\\u0644\\u064a\\u0648\\u0645 \\u0639\\u0646 \\u0628\\u0639\\u062f\"}', NULL, '2024-03-17 13:21:34', '2024-03-17 13:21:34');
INSERT INTO `frontends` (`id`, `data_keys`, `data_values`, `tempname`, `created_at`, `updated_at`) VALUES
(190, 'program_duration.element', '{\"title\":\"Availability of a computer and the Internet is required\",\"title_ar\":\"\\u0645\\u0637\\u0644\\u0648\\u0628 \\u062a\\u0648\\u0627\\u0641\\u0631 \\u062c\\u0647\\u0627\\u0632 \\u0643\\u0645\\u0628\\u064a\\u0648\\u062a\\u0631 \\u0648\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a\"}', NULL, '2024-03-17 13:21:50', '2024-03-17 13:21:50'),
(191, 'program_duration.element', '{\"title\":\"Training according to an intensive training program\",\"title_ar\":\"\\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0648\\u0641\\u0642 \\u0628\\u0631\\u0646\\u0627\\u0645\\u062c \\u062a\\u062f\\u0631\\u064a\\u0628\\u064a \\u0645\\u0643\\u062b\\u0641\"}', NULL, '2024-03-17 13:22:04', '2024-03-17 13:22:04'),
(192, 'program_duration.element', '{\"title\":\"Integrated guidance forums of experts in several fields according to the highest standards\",\"title_ar\":\"\\u0645\\u0646\\u062a\\u062f\\u064a\\u0627\\u062a \\u0625\\u0631\\u0634\\u0627\\u062f\\u064a\\u0629 \\u0645\\u062a\\u0643\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0644\\u062e\\u0628\\u0631\\u0627\\u0621 \\u0641\\u064a \\u0639\\u062f\\u0629 \\u0645\\u062c\\u0627\\u0644\\u0627\\u062a \\u0648\\u0641\\u0642 \\u0623\\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0639\\u0627\\u064a\\u064a\\u0631\"}', NULL, '2024-03-17 13:22:18', '2024-03-17 13:22:18'),
(193, 'program_duration.element', '{\"title\":\"Weekly evaluation\",\"title_ar\":\"\\u0627\\u0644\\u062a\\u0642\\u064a\\u064a\\u0645 \\u0627\\u0644\\u0623\\u0633\\u0628\\u0648\\u0639\\u064a\"}', NULL, '2024-03-17 13:22:34', '2024-03-17 13:22:34'),
(194, 'program_duration.element', '{\"title\":\"Enable the trainee to acquire the necessary concepts and skills to perform his duties to the fullest\",\"title_ar\":\"\\u062a\\u0645\\u0643\\u064a\\u0646 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0631\\u0628 \\u0645\\u0646 \\u0627\\u0643\\u062a\\u0633\\u0627\\u0628 \\u0627\\u0644\\u0645\\u0641\\u0627\\u0647\\u064a\\u0645 \\u0648\\u0627\\u0644\\u0645\\u0647\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0644\\u0627\\u0632\\u0645\\u0629 \\u0644\\u0623\\u062f\\u0627\\u0621 \\u0648\\u0627\\u062c\\u0628\\u0627\\u062a\\u0647 \\u0639\\u0644\\u0649 \\u0623\\u0643\\u0645\\u0644 \\u0648\\u062c\\u0647\"}', NULL, '2024-03-17 13:22:47', '2024-03-17 13:22:47'),
(195, 'submission_criteria.content', '{\"has_image\":\"1\",\"heading\":\"Submission Criteria\",\"heading_ar\":\"\\u0645\\u0639\\u0627\\u064a\\u064a\\u0631 \\u0627\\u0644\\u062a\\u0642\\u062f\\u064a\\u0645\",\"button\":\"Apply Now\",\"button_ar\":\"\\u0642\\u062f\\u0645 \\u0627\\u0644\\u0622\\u0646\",\"button_link\":\"https:\\/\\/docs.google.com\\/forms\\/d\\/1mKIpk2WPI1NCXrdJme1pngFmHQFfCOUSAKdxk3H0Mlk\\/viewform?edit_requested=true\",\"image\":\"65f745d16bbbe1710704081.png\",\"icon\":\"65f745d1a37df1710704081.png\"}', NULL, '2024-03-17 13:34:41', '2024-03-17 13:34:41'),
(196, 'submission_criteria.element', '{\"title\":\"Once the application is received, our team will study the candidates\",\"title_ar\":\"\\u0628\\u0645\\u062c\\u0631\\u062f \\u0627\\u0633\\u062a\\u0644\\u0627\\u0645 \\u0627\\u0644\\u0637\\u0644\\u0628 \\u060c \\u0633\\u064a\\u0642\\u0648\\u0645 \\u0641\\u0631\\u064a\\u0642\\u0646\\u0627 \\u0628\\u062f\\u0631\\u0627\\u0633\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0634\\u062d\\u064a\\u0646\"}', NULL, '2024-03-17 13:35:07', '2024-03-17 13:35:07'),
(197, 'submission_criteria.element', '{\"title\":\"They are contacted for an initial telephone interview\",\"title_ar\":\"\\u064a\\u062a\\u0645 \\u0627\\u0644\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0628\\u0647\\u0645 \\u0644\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0645\\u0642\\u0627\\u0628\\u0644\\u0629 \\u0647\\u0627\\u062a\\u0641\\u064a\\u0629 \\u0623\\u0648\\u0644\\u064a\\u0629\"}', NULL, '2024-03-17 13:35:23', '2024-03-17 13:35:23'),
(198, 'submission_criteria.element', '{\"title\":\"Bring the selected candidates to join the training course by e-mail\",\"title_ar\":\"\\u0625\\u062d\\u0636\\u0627\\u0631 \\u0627\\u0644\\u0645\\u0631\\u0634\\u062d\\u064a\\u0646 \\u0627\\u0644\\u0645\\u062e\\u062a\\u0627\\u0631\\u064a\\u0646 \\u0644\\u0644\\u0627\\u0646\\u0636\\u0645\\u0627\\u0645 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u062f\\u0648\\u0631\\u0629 \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628\\u064a\\u0629 \\u0639\\u0646 \\u0637\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0628\\u0631\\u064a\\u062f \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a\"}', NULL, '2024-03-17 13:35:39', '2024-03-17 13:35:39'),
(199, 'submission_criteria.element', '{\"title\":\"Invite candidates whose needs and motivations align with our mission for a one-on-one interview in our offices\",\"title_ar\":\"\\u0642\\u0645 \\u0628\\u062f\\u0639\\u0648\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0634\\u062d\\u064a\\u0646 \\u0627\\u0644\\u0630\\u064a\\u0646 \\u062a\\u062a\\u0648\\u0627\\u0641\\u0642 \\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a\\u0647\\u0645 \\u0648\\u062f\\u0648\\u0627\\u0641\\u0639\\u0647\\u0645 \\u0645\\u0639 \\u0645\\u0647\\u0645\\u062a\\u0646\\u0627 \\u0644\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0645\\u0642\\u0627\\u0628\\u0644\\u0629 \\u0641\\u0631\\u062f\\u064a\\u0629 \\u0641\\u064a \\u0645\\u0643\\u0627\\u062a\\u0628\\u0646\\u0627\"}', NULL, '2024-03-17 13:35:51', '2024-03-17 13:35:51'),
(200, 'submission_criteria.element', '{\"title\":\"Responding to applicants and communicating with them to study the cases of applicants through the Hemam Call Center platform\",\"title_ar\":\"\\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0644\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645\\u064a\\u0646 \\u0648\\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0647\\u0645 \\u0644\\u062f\\u0631\\u0627\\u0633\\u0629 \\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645\\u064a\\u0646 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0645\\u0646\\u0635\\u0629 \\u0645\\u0631\\u0643\\u0632 \\u0627\\u062a\\u0635\\u0627\\u0644 \\u0647\\u0645\\u0627\\u0645\"}', NULL, '2024-03-17 13:36:05', '2024-03-17 13:36:05'),
(201, 'service_section.element', '{\"has_image\":\"1\",\"title\":\"Reconciling relations\",\"title_ar\":\"\\u0625\\u0635\\u0644\\u0627\\u062d \\u0630\\u0627\\u062a \\u0627\\u0644\\u0628\\u064a\\u0646\",\"short_description\":\"We fully believe Amlaek in the importance of eliminating the causes of disputes and conflict, through tolerance and forgiveness, or by mutual consent. This is represented in the importance of reconciling relations between a single family, partners and family companies.\",\"short_description_ar\":\"\\u0646\\u062d\\u0646 \\u0646\\u0648\\u0645\\u0646 \\u0627\\u064a\\u0645\\u0627\\u0646 \\u062a\\u0627\\u0645 \\u0641\\u064a \\u062a\\u0646\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0627\\u0645\\u0644\\u0627\\u0643 \\u0628\\u0623\\u0647\\u0645\\u064a\\u0629 \\u0625\\u0632\\u0627\\u0644\\u0629 \\u0623\\u0633\\u0628\\u0627\\u0628 \\u0627\\u0644\\u062e\\u0635\\u0627\\u0645 \\u0648\\u0627\\u0644\\u0646\\u0632\\u0627\\u0639\\u060c \\u0628\\u0627\\u0644\\u062a\\u0651\\u0633\\u0627\\u0645\\u062d \\u0648\\u0627\\u0644\\u0639\\u0641\\u0648\\u060c \\u0623\\u0648 \\u0628\\u0627\\u0644\\u062a\\u0651\\u0631\\u0627\\u0636\\u064a, \\u0648\\u064a\\u062a\\u0645\\u062b\\u0644 \\u0630\\u0644\\u0643 \\u0628\\u0623\\u0647\\u0645\\u064a\\u0629 \\u0627\\u0635\\u0644\\u0627\\u062d \\u0627\\u0644\\u0628\\u064a\\u0646 \\u0628\\u064a\\u0646 \\u0627\\u0644\\u0627\\u0633\\u0631\\u0629 \\u0627\\u0644\\u0648\\u0627\\u062d\\u062f\\u0629 \\u0648\\u0627\\u0644\\u0634\\u0631\\u0643\\u0627\\u0621 \\u0648\\u0627\\u0644\\u0634\\u0631\\u0643\\u0627\\u062a \\u0627\\u0644\\u0639\\u0627\\u0626\\u0644\\u064a\\u0629\",\"button_url\":\"service-request\",\"image\":\"65f87128af1e51710780712.png\"}', NULL, '2024-03-18 15:51:52', '2024-03-18 15:51:52'),
(202, 'service_section.element', '{\"has_image\":\"1\",\"title\":\"Taqbeel of projects\",\"title_ar\":\"\\u062a\\u0642\\u0628\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0634\\u0627\\u0631\\u064a\\u0639\",\"short_description\":\"Offers to accept projects with their assets and liabilities according to the agreement between the parties\",\"short_description_ar\":\"\\u0639\\u0631\\u0648\\u0636 \\u062a\\u0642\\u0628\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0634\\u0627\\u0631\\u064a\\u0639 \\u0628\\u0645\\u0627 \\u0644\\u0647\\u0627 \\u0648\\u0639\\u0644\\u064a\\u0647\\u0627 \\u0645\\u0646 \\u0623\\u0635\\u0648\\u0644 \\u0648\\u062e\\u0635\\u0648\\u0645 \\u0628\\u0645\\u0648\\u062c\\u0628 \\u0627\\u0644\\u0625\\u062a\\u0641\\u0627\\u0642 \\u0628\\u064a\\u0646 \\u0627\\u0644\\u0623\\u0637\\u0631\\u0627\\u0641\",\"button_url\":\"service-request\",\"image\":\"65f8720ca8f871710780940.png\"}', NULL, '2024-03-18 15:52:33', '2024-03-18 15:55:40'),
(203, 'service_section.element', '{\"has_image\":\"1\",\"title\":\"Project processing\",\"title_ar\":\"\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0627\\u0644\\u0645\\u0634\\u0627\\u0631\\u064a\\u0639\",\"short_description\":\"Providing all solutions for treatment according to the status of each stalled project\\n1. Rehabilitation of the project.\\n2. Refinancing the project.\\n3. Scheduling installments for bad debt.\\n4. Transferring the debt to a new investor.\\n5. Renting the project to an investor who wants to invest without transferring ownership.\\n6. The defaulter enters into a partnership with a new investor.\\n7. Coordination with the Ministry of Agriculture, Water and Environment regarding licenses, such as changing activity, renewing the license, etc.\",\"short_description_ar\":\"\\u062a\\u0642\\u062f\\u064a\\u0645 \\u0643\\u0627\\u0641\\u0629 \\u0627\\u0644\\u062d\\u0644\\u0648\\u0644 \\u0644\\u0644\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u062d\\u0633\\u0628 \\u062d\\u0627\\u0644\\u0629 \\u0643\\u0644 \\u0645\\u0634\\u0631\\u0648\\u0639 \\u0645\\u062a\\u0639\\u062b\\u0631 \\n1.\\t\\u0625\\u0639\\u0627\\u062f\\u0629 \\u062a\\u0623\\u0647\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0634\\u0631\\u0648\\u0639.\\n2.\\t\\u0625\\u0639\\u0627\\u062f\\u0629 \\u062a\\u0645\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0634\\u0631\\u0648\\u0639.\\n3.\\t\\u062c\\u062f\\u0648\\u0644\\u0629 \\u0623\\u0642\\u0633\\u0627\\u0637 \\u0627\\u0644\\u062f\\u064a\\u0646 \\u0627\\u0644\\u0645\\u062a\\u0639\\u062b\\u0631.\\n4.\\t\\u0646\\u0642\\u0644 \\u0627\\u0644\\u0645\\u062f\\u064a\\u0648\\u0646\\u064a\\u0629 \\u0644\\u0645\\u0633\\u062a\\u062b\\u0645\\u0631 \\u062c\\u062f\\u064a\\u062f.\\n5.\\t\\u062a\\u0623\\u062c\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0634\\u0631\\u0648\\u0639 \\u0644\\u0645\\u0633\\u062a\\u062b\\u0645\\u0631 \\u064a\\u0631\\u063a\\u0628 \\u0628\\u0627\\u0644\\u0627\\u0633\\u062a\\u062b\\u0645\\u0627\\u0631 \\u062f\\u0648\\u0646 \\u0646\\u0642\\u0644 \\u0627\\u0644\\u0645\\u0644\\u0643\\u064a\\u0629.\\n6.\\t\\u062f\\u062e\\u0648\\u0644 \\u0627\\u0644\\u0645\\u062a\\u0639\\u062b\\u0631 \\u0641\\u064a \\u0634\\u0631\\u0627\\u0643\\u0629 \\u0645\\u0639 \\u0645\\u0633\\u062a\\u062b\\u0645\\u0631 \\u062c\\u062f\\u064a\\u062f.\\n7.\\t\\u0627\\u0644\\u062a\\u0646\\u0633\\u064a\\u0642 \\u0645\\u0639 \\u0648\\u0632\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0648\\u0627\\u0644\\u0645\\u064a\\u0627\\u0647 \\u0648\\u0627\\u0644\\u0628\\u064a\\u0626\\u0629 \\u0641\\u064a\\u0645\\u0627 \\u064a\\u062e\\u0635 \\u0627\\u0644\\u062a\\u0631\\u0627\\u062e\\u064a\\u0635 \\u0643\\u062a\\u063a\\u064a\\u064a\\u0631 \\u0627\\u0644\\u0646\\u0634\\u0627\\u0637\\u060c \\u062a\\u062c\\u062f\\u064a\\u062f \\u0627\\u0644\\u0631\\u062e\\u0635\\u0629...\\u0625\\u0644\\u062e\",\"button_url\":\"service-request\",\"image\":\"65f871fa7da111710780922.png\"}', NULL, '2024-03-18 15:54:51', '2024-03-18 15:55:22');

